query MyQuery{
  MileageRule(where: {isDeleted: {_eq: false}}) {
    id
    code
    ruleOrder
    mileageRuleDetail {
      id
      version
      detailOrder
    }
  }
}

query MyQuery($validFrom: timestamptz, $validTo: timestamptz) {
   ExpenseRequest(where: {createdAt: {_gt: $validFrom, _lt: $validTo}, _and: {isDeleted: {_eq: false}}}) {
    createdAt
    title
    status
    totalAmount
    employee {
      firstName
      lastName
    }
  }
  ExpensePlan(where: {createdAt: {_gt: $validFrom, _lt: $validTo}, _and: {isDeleted: {_eq: false}}}) {
    createdAt
    title
    status
    totalAmount
    employee {
      firstName
      lastName
    }
  }
}

comp.script:
const allExpenses = []
const expensePlan = fetchExpenses.data.data.ExpensePlan
const expenseRequest = fetchExpenses.data.data.ExpenseRequest

expensePlan.map((item) => {
  allExpenses.push({
    "createdAt": item.createdAt,
    "title": item.title,
    "status": item.status,
    "totalAmount": item.totalAmount,
    "employee": {"firstName": item.employee.firstName,
                "lastName": item.employee.lastName},
    "type": 'Expense Plan'
  })

})

expenseRequest.map((item) => {
  allExpenses.push({
    "createdAt": item.createdAt,
    "title": item.title,
    "status": item.status,
    "totalAmount": item.totalAmount,
    "employee": {"firstName": item.employee.firstName,
                "lastName": item.employee.lastName},
     "type": 'Expense Request'
  })

})

return allExpenses

const allData = fetchMileages?.data?.data?.MileageRule; 
const newOrder = currentRuleOrders.value;
const currentEntryId = additionalData?.midValue?.nvi_navigationPayload?.id;

for (const entry of allData) {
    const entryCodeOrder = entry.ruleOrder;

    if (entry.id === currentEntryId) {
        continue;
    }

    const isMatchingOrder = entryCodeOrder === newOrder;

    if (isMatchingOrder) {
        overlapingOrderState.setValue(true);
        return true;
    }
}

overlapingOrderState.setValue(false);
return false;

const allData = fetchMileages?.data?.data?.MileageRule; 
const newOrder = detailOrder.value;
const currentEntryId = additionalData?.midValue?.nvi_navigationPayload?.id;

for (const entry of allData) {
  for (const detail of entry.mileageRuleDetail) {
     const entryDetailOrder = detail.detailOrder;

    if (entry.id === currentEntryId) {
            continue;
    }

    const isMatchingOrder = entryDetailOrder === newOrder;

    if (isMatchingOrder) {
        overlapingDetailOrderState.setValue(true);
        return true;
    }
  }
}

overlapingDetailOrderState.setValue(false);
return false;

const rowSelected = isClicked.value;
const selectedMileageDetails = rowSelected ? allRules.selectedRow : {};
const {id, tempId} = selectedMileageDetails;

const mileageDetails = {
    ...selectedMileageDetails,
    limitFrom: currentLimitFrom?.value,
    limitTo: currentLimitTo?.value,
    amount: currentAmount?.value,
    detailOrder: detailOrder?.value,
    activeFrom: window.lowcoder.formatDateToISO(currentValidFrom.value) || new Date(currentValidFrom.value).toISOString(),
    activeTo:window.lowcoder.formatDateToISO(currentValidTo.value) ||  new Date(currentValidTo.value).toISOString()  
};

if (!id && !tempId) {
  // add to table
  tempMileageDetails.setValue([
      ...(tempMileageDetails?.value ?? []),
      {...mileageDetails, tempId: Date.now()}
  ])

  // add to save list
  toSaveMileageDetails.setValue([
      ...(toSaveMileageDetails?.value ?? []),
      {...mileageDetails, tempId: Date.now()}
  ])
} else {
  // update record in display list
  const updateDisplayList = [...tempMileageDetails?.value];
  const displayListIndex = updateDisplayList.findIndex(record => {
      return id ? record.id == id : record.tempId == tempId;
  });
  if (displayListIndex > -1) {
    updateDisplayList.splice(displayListIndex,1,{...mileageDetails});
    tempMileageDetails.setValue(updateDisplayList);  
  }

  // upadte record in savelist
  const updateSaveList = [...toSaveMileageDetails?.value];
  const saveListIndex = updateSaveList.findIndex(record => {
      return id ? record.id == id : record.tempId == tempId;
  });

  if (saveListIndex > -1) {
    updateSaveList.splice(saveListIndex,1,{...mileageDetails});
    toSaveMileageDetails.setValue(updateSaveList); 
  } else {
    // add to save list
    toSaveMileageDetails.setValue([
        ...(toSaveMileageDetails?.value ?? []),
        {...mileageDetails, tempId: Date.now()}
    ])
  }
}

transformers.script:
const date = new Date()

const day = date.getDate();
const month = date.getMonth() + 1; 
const year = date.getFullYear(); 

const formattedDate = `${year < 10 ? '0' : ''}${year}.${month < 10 ? '0' : ''}${month}.${day < 10 ? '0' : ''}${day}`;

return formattedDate;

function findCode(code) {
    const allData = fetchMileages?.data?.data?.MileageRule; 
    const allCodes = allData.map((item) => item.code);

    if (code === '' || code === undefined) {
        return window.lowcoder.translate('lowcoder:expense_calculation_rule.expense_calculation_rule_modal.is_code_unique_second', "The 'Rule Code' field is required.");
    }

    const lowerCasedCodes = allCodes.map(item => item.toLowerCase());
    if (lowerCasedCodes.includes(code.toLowerCase())) {
        return window.lowcoder.translate('lowcoder:expense_calculation_rule.expense_calculation_rule_modal.is_code_unique_second', 'This code already exists') ;
    }

    return ''; 
}
return findCode

return changeCondition.value ? {
    "mileageRule": {
    "id": additionalData.value.nvi_navigationPayload.id,
    "version": additionalData.value.nvi_navigationPayload.version,
    "code": currentRuleCode.value.trim().replace(/\s+/g, ' '),
    "name": currentRuleName.value.trim().replace(/\s+/g, ' '),
    "ruleOrder": currentRuleOrders.value,
    "rulePeriod": currentRulePeriod.value,
    "activeFrom": window.lowcoder.formatDateToISO(validFrom.value)||validFrom.value?.concat('T','00:00:00.000Z'),
    "activeTo": window.lowcoder.formatDateToISO(validTo.value)||validTo.value?.concat('T','00:00:00.000Z')
  },
  "changeMode": "UPDATE"
} : {
  "mileageRule": {
    "code": currentRuleCode.value.trim().replace(/\s+/g, ' '),
    "name": currentRuleName.value.trim().replace(/\s+/g, ' '),
    "rulePeriod": currentRulePeriod.value,
    "ruleOrder": currentRuleOrders.value,
    "activeFrom": window.lowcoder.formatDateToISO(validFrom.value)||validFrom.value?.concat('T','00:00:00.000Z'),
    "activeTo": window.lowcoder.formatDateToISO(validTo.value)||validTo.value?.concat('T','00:00:00.000Z')
  },
  "changeMode": "INSERT"
}

function validateMilageRuleDetail(limitFrom, limitTo, detailActiveFrom, detailActiveTo, currentIndex) {
    const allMileageRules = changeCondition.value ? fetchMileagePerRule.data.data.MileageRule[0].mileageRuleDetail : tempMileageDetails.value;
    const newDetailActiveFrom = new Date(detailActiveFrom);
    const newDetailActiveTo = new Date(detailActiveTo);

    for (let i = 0; i < allMileageRules.length; i++) {
        if (i === currentIndex) {
            continue;
        }

        const existingDetail = allMileageRules[i];
        const existingLimitFrom = existingDetail.limitFrom;
        const existingLimitTo = existingDetail.limitTo;
        const existingActiveFrom = new Date(existingDetail.activeFrom);
        const existingActiveTo = new Date(existingDetail.activeTo);

        const isLimitOverlap = (
            (limitFrom <= existingLimitTo && limitTo >= existingLimitFrom)
        );

        const isPeriodOverlap = (
            newDetailActiveFrom <= existingActiveTo && newDetailActiveTo >= existingActiveFrom
        );

        if (isLimitOverlap && isPeriodOverlap) {
            return false;
        }
    }

    return true;
}
return validateMilageRuleDetail

let validation = false
if (
    fetchMileagePerRule.data.data.MileageRule[0].mileageRuleDetail[0].limitFrom == currentLimitFrom.value &&
